-- Kiểm tra media_items sau migrate
SELECT id, filename, LEFT(thumbUrl, 80) as thumbUrl FROM media_items ORDER BY createdAt DESC LIMIT 3;

-- Kiểm tra còn URL nào dùng CDN không
SELECT COUNT(*) as cdn_media_count FROM media_items WHERE thumbUrl LIKE 'https://media.yukvix.com/%';
SELECT COUNT(*) as cdn_photos_count FROM photos WHERE thumbUrl LIKE 'https://media.yukvix.com/%';
SELECT COUNT(*) as direct_media_count FROM media_items WHERE thumbUrl LIKE 'https://s3.ap-southeast-1%';

